          {
            "name": "Kubota",
            "kind": "private",
            "note": "Strong in compact/small-ag and Asia; smaller-equipment share pressure, not the large-ag core.",
            "growth": null,
            "margin": null,
            "multiple": "~12x P/E"
          }
